@props(['inset' => false, 'variant' => 'default', 'disabled' => false])

<div
    role="menuitem"
    tabindex="{{ $disabled ? '-1' : '0' }}"
    x-on:click="selectItem($el)"
    data-slot="context-menu-item"
    data-variant="{{ $variant }}"
    @if ($inset) data-inset @endif
    @if ($disabled) data-disabled aria-disabled="true" @endif
    {{ $attributes->except('disabled')->twMerge(['class' => "relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 data-[inset]:pl-8 data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive dark:data-[variant=destructive]:focus:bg-destructive/20 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground"]) }}
>
    {{ $slot }}
</div>

@props(['inset' => false])

<div
    data-slot="context-menu-label"
    @if ($inset) data-inset @endif
    {{ $attributes->twMerge(['class' => 'px-2 py-1.5 text-sm font-medium text-foreground data-[inset]:pl-8']) }}
>
    {{ $slot }}
</div>

import { anchor } from '@alpinejs/anchor';
import { use } from './lib/plugins.js';
import { menuNavigation, dropdownMenuCheckbox, dropdownMenuRadioGroup, dropdownMenuSub } from './lib/menu.js';

const contextMenu = (open = false) => ({
    ...menuNavigation,
    open,
    trigger: null,
    content: null,
    x: 0,
    y: 0,
    registerTrigger(trigger) {
        this.trigger = trigger;
        trigger?.setAttribute('aria-haspopup', 'menu');
    },
    registerContent(content) {
        this.content = content;

        if (this.open) {
            this.$nextTick(() => this.positionContent());
        }
    },
    openMenu(event) {
        this.trigger = event.currentTarget;

        if (event.type === 'contextmenu') {
            this.x = event.clientX;
            this.y = event.clientY;
        } else {
            const rect = this.trigger.getBoundingClientRect();
            this.x = rect.left;
            this.y = rect.bottom;
        }

        this.open = true;
        this.$nextTick(() => {
            this.positionContent();
            this.focusItem(this.content, 'first');
        });
    },
    closeMenu(restoreFocus = true) {
        if (!this.open) {
            return;
        }

        this.open = false;

        if (restoreFocus) {
            this.$nextTick(() => this.trigger?.focus());
        }
    },
    handleTriggerKeydown(event) {
        if (event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10')) {
            event.preventDefault();
            this.openMenu(event);
        }
    },
    handleKeydown(event) {
        this.handleMenuKeydown(event, () => this.closeMenu());
    },
    selectItem(item) {
        if (!item.hasAttribute('data-disabled')) {
            this.closeMenu();
        }
    },
    positionContent() {
        if (!this.content) {
            return;
        }

        const padding = 8;
        const left = Math.min(this.x, Math.max(padding, window.innerWidth - this.content.offsetWidth - padding));
        const top = Math.min(this.y, Math.max(padding, window.innerHeight - this.content.offsetHeight - padding));

        Object.assign(this.content.style, {
            left: `${Math.max(padding, left)}px`,
            top: `${Math.max(padding, top)}px`,
        });
        this.content.dataset.side = top < this.y ? 'top' : 'bottom';
    },
});

export default function (Alpine) {
    use(Alpine, anchor);
    Alpine.data('uiContextMenu', contextMenu);
    Alpine.data('uiContextMenuCheckbox', dropdownMenuCheckbox);
    Alpine.data('uiContextMenuRadioGroup', dropdownMenuRadioGroup);
    Alpine.data('uiContextMenuSub', dropdownMenuSub);
}
